const buffer = 32;
let tokensLeft = modelMaxTokens - countTokens(modifiedPrompt) - buffer - completionMinTokens;
if (contextsEnhancement.contextDocumentValue) {
  let context = "";
  context += `Context documents:\n\n`;
  context += `---\n\n`;
  context += `${fitToMaxTokens(
    contextsEnhancement.contextDocumentValue,
    tokensLeft / 2 // TODO ideally we'd split proportional to size
  )}\n\n`;
  context += `---\n\n`;
  // prepend
  modifiedPrompt = context + modifiedPrompt;
  tokensLeft -= countTokens(context);
}
if (chatContextEnhancement.contextRelevantExperimentalTextData) {
  // prepend
  modifiedPrompt =
  `${fitToMaxTokens(
    chatContextEnhancement.contextRelevantExperimentalTextData,
    tokensLeft
  )}\n\n\n` + modifiedPrompt;
