    write(sock, "Benutzername\r\n", strlen("Benutzername\r\n"));
    write(sock, "Passwort\r\n", strlen("Passwort\r\n"));

    // Senden anderer SSH-Befehle
    write(sock, "BEFEHL\r\n", strlen("BEFEHL\r\n"));

    // Schließen des Sockets
    close(sock);
    return 0;
}
