    if (write(sock, "Benutzername\r\n", strlen("Benutzername\r\n")) < 0) {
        perror("Fehler beim Senden des Benutzernamens");
        return 1;
    }
    if (write(sock, "Passwort\r\n", strlen("Passwort\r\n")) < 0) {
        perror("Fehler beim Senden des Passworts");
