    int32 id = 1;
    string name = 2;
    string email = 3;
    string password = 4;
}
message UpdateUserRequest {
    int32 id = 1;
    string name = 2;
    string email = 3;
    string password = 4;
}
message UpdateUserResponse {
    string message = 1;
}
message DeleteUserRequest {
    int32 id = 1;
}
message DeleteUserResponse {
    string message = 1;
}
```

3. Generieren Sie PHP-Klassen aus Proto-Datei
Führen Sie folgenden Befehl aus, um PHP-Klassen aus der Datei `users.proto` zu generieren:
```
php artisan proto:generate
```
Dies erzeugt PHP-Klassen im Verzeichnis `app/Protos/Users`.

